INSERT INTO feature VALUES('corpus-comments','corpus','Every corpus item and block member commented, in one shape','corpus-expectations','implemented','ordinary',NULL,'A gate refuses a corpus item without a comment before its attribute block, and a member of a theory, module, data or codata block without a comment before it; a source''s head is four paragraphs (what, why, how, references) and an item comment at most two short sentences, each finding a ledger line of its kind.','surface-corpus','crates/surface-corpus/tests/comments.rs',NULL,'#355');
